CREATE OR REPLACE FUNCTION public.internal_complete_sale(p jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare sid uuid; cid uuid; lid uuid; lineid uuid; r record; j jsonb; total numeric:=0; calc numeric:=0; rate numeric; cp numeric; fp numeric; paid numeric; n int; k int; firstdate date; due date; base numeric; loan numeric; inv text; sdate date; today date:=(now() at time zone 'Asia/Colombo')::date;
begin if not exists(select 1 from public.user_roles where user_id=auth.uid()) then raise exception 'Staff login required'; end if; if jsonb_array_length(p->'lines')=0 then raise exception 'Add at least one piece'; end if; if (select count(distinct x->>'id') from jsonb_array_elements(p->'lines') x)<>jsonb_array_length(p->'lines') then raise exception 'Duplicate piece'; end if;
 sdate:=today;
 if nullif(p->>'sale_date','') is not null then
   if p->>'sale_date' !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' then raise exception 'Enter a valid sale date'; end if;
   sdate:=(p->>'sale_date')::date;
   if sdate>today then raise exception 'The sale date cannot be in the future'; end if;
   if sdate<date '2000-01-01' then raise exception 'The sale date is too far in the past'; end if;
 end if;
 perform 1 from public.items where id in(select (x->>'id')::uuid from jsonb_array_elements(p->'lines') x) order by id for update;
for j in select * from jsonb_array_elements(p->'lines') loop select * into r from public.items where id=(j->>'id')::uuid; if not found or r.status<>'In Stock' then raise exception 'Piece not found or already sold'; end if; rate:=round((j->>'rate_used')::numeric,2); if rate is null or rate<=0 or rate::text in ('NaN','Infinity','-Infinity') then raise exception 'Enter a positive price per gram for every piece'; end if; fp:=round((j->>'final_price')::numeric,2); if fp is null or fp<0 then raise exception 'Invalid final price'; end if; select purchase_price into cp from public.item_costs where item_id=r.id; if fp<cp and coalesce((p->>'confirm_below_cost')::boolean,false)=false then raise exception 'BELOW_COST'; end if; total:=total+fp; calc:=calc+round(r.weight*case when j->>'price_unit'='Pound (8g)' then (j->>'unit_price')::numeric/8 else rate end,2); end loop;
if total<=0 then raise exception 'Bill total must be positive'; end if; paid:=round((p->>'paid_now')::numeric,2); if p->>'payment_type'='Full Payment' then paid:=total; elsif p->>'payment_type'='Full Loan' then paid:=0; elsif p->>'payment_type'='Cash + Loan' then if paid is null or paid<=0 or paid>=total then raise exception 'Paid now must be between zero and total'; end if; else raise exception 'Invalid payment type'; end if; if p->>'payment_method' not in('Cash','Card','Bank Transfer','Mixed','Cheque') then raise exception 'Invalid payment method'; end if; loan:=total-paid;
if loan>0 and (nullif(trim(p->>'customer_name'),'') is null or nullif(trim(p->>'customer_phone'),'') is null) then raise exception 'Customer name and phone required for loans'; end if;
if nullif(trim(p->>'customer_phone'),'') is not null then insert into public.customers(name,phone) values(coalesce(nullif(trim(p->>'customer_name'),''),'Customer'),trim(p->>'customer_phone')) on conflict(phone) do update set name=excluded.name returning id into cid; end if;
insert into public.sales(customer_id,payment_type,payment_method,calculated_total,final_total,paid_now,loan_amount,created_by,"date") values(cid,p->>'payment_type',p->>'payment_method',calc,total,paid,loan,auth.uid(),sdate) returning id,invoice_no into sid,inv;
for j in select * from jsonb_array_elements(p->'lines') loop select i.*,m.name metal into r from public.items i join public.metal_types m on m.id=i.metal_id where i.id=(j->>'id')::uuid; rate:=round((j->>'rate_used')::numeric,2); insert into public.sale_items(sale_id,item_id,tag_id,name,metal,weight,rate_used,calculated_price,final_price) values(sid,r.id,r.tag_id,r.name,r.metal,r.weight,rate,round(r.weight*case when j->>'price_unit'='Pound (8g)' then (j->>'unit_price')::numeric/8 else rate end,2),round((j->>'final_price')::numeric,2)) returning id into lineid; insert into public.sale_costs select lineid,purchase_price from public.item_costs where item_id=r.id; update public.items set status='Sold',sold_invoice=inv where id=r.id; end loop;
if loan>0 then n:=(p->>'installments')::int; if n is null or n<1 or n>120 then raise exception 'Installments must be 1–120'; end if; if p->>'frequency' not in('Monthly','Every 2 weeks','Weekly') then raise exception 'Invalid frequency'; end if; firstdate:=(p->>'first_due')::date; if firstdate is null or firstdate<sdate then raise exception 'First due date must be on or after the sale date'; end if; insert into public.loans(sale_id,customer_id,amount,frequency) values(sid,cid,loan,p->>'frequency') returning id into lid; base:=floor(loan*100/n)/100; for k in 1..n loop if p->>'frequency'='Monthly' then due:=(date_trunc('month',firstdate)+(k-1)*interval '1 month')::date; due:=due+least(extract(day from firstdate)::int,extract(day from (due+interval '1 month - 1 day'))::int)-1; else due:=firstdate+(k-1)*case when p->>'frequency'='Weekly' then 7 else 14 end; end if; insert into public.loan_installments(loan_id,installment_no,due_date,amount) values(lid,k,due,case when k=n then loan-base*(n-1) else base end); end loop; end if; return sid; end
$function$;